import java.util.HashMap;
import java.util.Map;

class Solution {
    public int singleNumber(int[] nums) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int value : nums) {
            frequency.put(value, frequency.getOrDefault(value, 0) + 1);
        }
        for (int value : nums) {
            if (frequency.get(value) == 1) {
                return value;
            }
        }
        return 0;
    }
}

